        planSha256: plan.planSha256,
        tenant: plan.tenant,
        state: 'started',
        startedAt: new Date()
      }
    }, {
      upsert: true
    });
    await db.collection('ui_meta').updateOne({
      _id: 'tenant'
    }, {
      $setOnInsert: {
        tenant: plan.tenant
      }
    }, {
      upsert: true
    });
    for (const [collection, records] of [
        ['ui_roles', plan.roles],
        ['ui_users', plan.users]
      ]) {
      await db.collection(collection).createIndex({
        id: 1
      }, {
        unique: true
      });
      for (const record of records) {
        const old = await db.collection(collection).findOne({
          id: record.id
        });
        if (old) {
          if (JSON.stringify(old) !== JSON.stringify({
              ...record,
              _id: old._id
            })) {
            // Real Mongo injects _id. Compare its removal without trusting arbitrary fields.
            const {
              _id: ignored,
              ...value
            } = old;
            if (JSON.stringify(value) !== JSON.stringify(record)) fail('MIGRATION_TARGET_CHANGED',
              'A partially migrated identity differs from the reviewed plan.');
          }
        } else await db.collection(collection).insertOne(record);
      }
    }
    await db.collection('ui_migrations').updateOne({
      _id: 'identity-v3'
    }, {
      $set: {
        state: 'complete',
        completedAt: new Date()
      }
    });
    return {
      state: 'complete',
      ...plan.summary
    };
  } finally {
    await locks.deleteOne({
      _id
    });
  }
}

